use clap::Parser;
use exposed::inbound::{
    cli::{Commands, ExposedCli, IntoResponse, Response, run_cli},
    http::server::run_server,
};

fn main() -> anyhow::Result<std::process::ExitCode> {
    let args = ExposedCli::parse();
    match args.command {
        Commands::Server => run_server().map(|()| std::process::ExitCode::SUCCESS),
        Commands::Data(args) => {
            dotenvy::dotenv().ok();
            let response = match tokio::runtime::Runtime::new() {
                Ok(runtime) => runtime.block_on(run_cli(args)),
                Err(error) => Err::<Response, _>(error).into_response(),
            };
            Ok(response.write_to(std::io::stdout().lock(), std::io::stderr().lock())?)
        }
    }
}
//! General purpose postgres client

use sqlx::PgPool;

/// Postgres client that wraps [`sqlx::Pool`]
#[derive(Clone)]
pub struct ExposedDatabase {
    pool: PgPool,
}

impl ExposedDatabase {
    /// Creates a new instance of [`ExposedDatabase`]
    ///
    /// # Errors
    /// Returns an error if the connection string is invalid or connecting fails.
    pub async fn new(conn_str: &str) -> sqlx::Result<Self> {
        let pool = PgPool::connect(conn_str).await?;

        Ok(Self { pool })
    }

    /// Get a reference to the underlying pool
    #[must_use]
    pub const fn pool(&self) -> &PgPool {
        &self.pool
    }
}

pub(super) fn word_similarity_candidate_threshold(strictness: f32) -> String {
    if strictness == 0.0 {
        return "0".into();
    }
    // pg_trgm's operator compares a double score before word_similarity rounds to real.
    f64::from(strictness)
        .midpoint(f64::from(strictness.next_down()))
        .to_string()
}

#[cfg(test)]
impl From<PgPool> for ExposedDatabase {
    fn from(value: PgPool) -> Self {
        Self { pool: value }
    }
}

#[cfg(test)]
mod test_scaffolding {
    use sqlx::PgPool;

    #[sqlx::test(migrations = "../db/migrations")]
    async fn migrations_work(pool: PgPool) -> sqlx::Result<()> {
        let res = sqlx::query!("SELECT name FROM members")
            .fetch_all(&pool)
            .await;
        assert!(res.is_ok());
        Ok(())
    }

    #[sqlx::test(
        migrations = "../db/migrations",
        fixtures(
            "../../../../db/fixtures/add_members.sql",
            "../../../../db/fixtures/add_declarations_and_funding_entries.sql"
        )
    )]
    async fn fixtures_work(pool: PgPool) -> sqlx::Result<()> {
        let res = sqlx::query!("SELECT name FROM members")
            .fetch_all(&pool)
            .await?;
        assert_eq!(res.len(), 2);

        let res = sqlx::query!("SELECT * FROM declarations")
            .fetch_all(&pool)
            .await?;
        assert_eq!(res.len(), 2);

        let res = sqlx::query!("SELECT * FROM funders")
            .fetch_all(&pool)
            .await?;
        assert_eq!(res.len(), 2);

        let res = sqlx::query!("SELECT * FROM funding_entries")
            .fetch_all(&pool)
            .await?;
        assert_eq!(res.len(), 2);

        Ok(())
    }
}
