//! Config for CLI

use anyhow::Context;
use std::{fs::read_to_string, io::Error as IoError, path::PathBuf};
use thiserror::Error;

use serde::{Deserialize, Serialize};

/// Environment configuration for data commands that use the database.
pub struct DataConfig {
    /// PostgreSQL connection string.
    pub connection_string: String,
}

impl DataConfig {
    /// Reads the database connection string from the environment.
    ///
    /// # Errors
    /// Returns an error if `DATABASE_URL` is missing or contains non-Unicode data.
    pub fn from_env() -> anyhow::Result<Self> {
        Ok(Self {
            connection_string: std::env::var("DATABASE_URL").context("DATABASE_URL must be set")?,
        })
    }
}

/// Configuration for capturing declarations for the stored member cohort.
#[derive(Serialize, Deserialize)]
pub struct DeclarationFetcherConfig {
    /// Root directory for ingestion datasets.
    pub data_dir: PathBuf,
    /// Nonzero API page size; validated when constructing the HTTP adapter.
    pub batch_size: u8,
}

impl TryFrom<&PathBuf> for DeclarationFetcherConfig {
    type Error = CliConfigError;

    fn try_from(value: &PathBuf) -> Result<Self, Self::Error> {
        let raw = read_to_string(value)?;
        Ok(rust_yaml::from_str(&raw)?)
    }
}

#[derive(Serialize, Deserialize)]
/// Config for the exposed application
pub struct FetcherConfig {
    /// Size of API batches
    pub batch_size: u8,
    /// Data store key
    pub data_dir: PathBuf,
}

impl TryFrom<&PathBuf> for FetcherConfig {
    type Error = CliConfigError;
    fn try_from(value: &PathBuf) -> Result<Self, Self::Error> {
        let raw = read_to_string(value)?;
        let config = rust_yaml::from_str(&raw)?;
        Ok(config)
    }
}

#[derive(Serialize, Deserialize)]
/// Config for the exposed application
pub struct LoaderConfig {
    /// Data store key
    pub data_dir: PathBuf,
}

impl TryFrom<&PathBuf> for LoaderConfig {
    type Error = CliConfigError;
    fn try_from(value: &PathBuf) -> Result<Self, Self::Error> {
        let raw = read_to_string(value)?;
        let config = rust_yaml::from_str(&raw)?;
        Ok(config)
    }
}

#[derive(Error, Debug)]
/// Collection of errors when parsing configuration
pub enum CliConfigError {
    #[error("yaml malformatted")]
    /// Yaml cannot be parsed
    FormattingError(#[from] rust_yaml::Error),
    #[error("unable to read config")]
    /// Config path invalid
    FileNotFound(#[from] IoError),
}

/// Runtime configuration for offline statistical declaration resolution.
#[derive(Deserialize)]
pub struct DeclarationResolverConfig {
    /// Root directory containing the existing ingestion run.
    pub data_dir: PathBuf,
    /// Maximum profile candidates and expanded observation pairs.
    #[serde(default = "default_candidate_budget")]
    pub candidate_budget: usize,
}
const fn default_candidate_budget() -> usize {
    1_000_000
}
impl TryFrom<&PathBuf> for DeclarationResolverConfig {
    type Error = anyhow::Error;
    fn try_from(path: &PathBuf) -> Result<Self, Self::Error> {
        let config: Self = rust_yaml::from_str(&read_to_string(path)?)?;
        anyhow::ensure!(
            config.candidate_budget > 0,
            "candidate_budget must be positive"
        );
        Ok(config)
    }
}
//! CLI inbound port

use schemars::JsonSchema;
use std::{path::PathBuf, str::FromStr};

use clap::{Parser, Subcommand};
use serde::Serialize;

use crate::{
    domain::{
        models::declaration_loading::DeclarationLoadOutcome,
        models::entity_ingestion::{
            DeclarationIngestionStage, EntityIngestionRequest, IngestionKey, MemberIngestionStage,
        },
        services::declaration_cleaning::DeclarationCleanerService,
        services::declaration_fetch::DeclarationFetcherService,
        services::declaration_loading::DeclarationLoaderService,
        services::declaration_resolution::DeclarationResolverService,
        services::entity_ingestion::{
            EntityFetcherService, EntityIngesterService, FetcherService, IngesterService,
        },
    },
    inbound::cli::config::{
        DataConfig, DeclarationFetcherConfig, DeclarationResolverConfig, FetcherConfig,
        LoaderConfig,
    },
    outbound::{ExposedDataPipeline, ExposedDatabase, ParliamentApiClient, WeldrsFunderScorer},
};

pub mod config;
pub mod response;
mod response_help;

pub use response::{CliSuccess, IntoResponse, Response};

/// CLI entrypoint for the `exposed` project
#[derive(Parser)]
pub struct ExposedCli {
    /// Commands for CLI
    #[command(subcommand)]
    pub command: Commands,
}

/// Run a server or prepare application data
#[derive(Subcommand)]
pub enum Commands {
    /// Start an instance of the `exposed` server
    Server,
    /// Options to run the `exposed` data pipeline
    Data(DataArgs),
}

/// CLI Data Args
#[derive(Parser)]
pub struct DataArgs {
    #[command(subcommand)]
    command: DataCommands,
}

/// CLI Subcommands
#[derive(Subcommand)]
#[allow(missing_docs)]
pub enum DataCommands {
    /// Show the latest ingestion key and directory path.
    #[command(after_long_help = response_help::single(latest))]
    Latest {
        /// YAML configuration with the ingestion `data_dir`.
        #[arg(long)]
        config: PathBuf,
    },
    /// Copy the latest raw capture into a new ingestion run.
    #[command(after_long_help = response_help::single(copy_latest_raw))]
    CopyLatestRaw {
        /// YAML configuration with the ingestion `data_dir`.
        #[arg(long)]
        config: PathBuf,
        /// Destination ingestion key. Defaults to a fresh UUID-v7.
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
    #[command(after_long_help = response_help::declarations())]
    Declarations {
        /// Stage to run: fetch, clean, resolve, or load.
        #[arg(value_parser = ["fetch", "clean", "resolve", "load"])]
        stage: String,
        /// YAML configuration containing the declaration `data_dir`.
        #[arg(long)]
        config: PathBuf,
        /// Ingestion run to clean, resolve, or load.
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
    #[command(after_long_help = response_help::single(members))]
    Members {
        stage: String,
        #[arg(long)]
        config: PathBuf,
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
}

/// Entry point for CLI commands
///
/// Command failures remain in the response until [`Response::write_to`] is called.
///
/// Failures include:
/// - Bad stage arg
/// - Bad config path
/// - Bad config shape
/// - Missing or non-Unicode `DATABASE_URL` for commands that use the database
/// - Service level failures
pub async fn run_cli(args: DataArgs) -> Response {
    match args.command {
        DataCommands::Latest { config } => latest(config).await.into_response(),
        DataCommands::CopyLatestRaw {
            config,
            ingestion_key,
        } => copy_latest_raw(config, ingestion_key).await.into_response(),
        DataCommands::Declarations {
            stage,
            config,
            ingestion_key,
        } => declarations(stage, config, ingestion_key).await,
        DataCommands::Members {
            stage,
            config,
            ingestion_key,
        } => members(stage, config, ingestion_key).await.into_response(),
    }
}

#[derive(Serialize, JsonSchema)]
struct IngestionResponse<T> {
    /// Ingestion result, or null when the store has no source runs.
    ingestion: Option<T>,
}

#[derive(Serialize, JsonSchema)]
struct IngestionLocation {
    ingestion_key: IngestionKey,
    /// Absolute ingestion run directory.
    path: PathBuf,
}

#[derive(Serialize, JsonSchema)]
struct CopiedIngestion {
    /// Run whose raw capture was copied.
    source_ingestion_key: IngestionKey,
    ingestion_key: IngestionKey,
    /// Absolute destination ingestion run directory.
    path: PathBuf,
}

#[derive(Serialize, JsonSchema)]
struct StageAcknowledgement<S> {
    ingestion_key: IngestionKey,
    stage: S,
    /// Absolute raw artifact: raw/declarations directory or raw/members.parquet file.
    path: PathBuf,
}

#[derive(Serialize, JsonSchema)]
struct DeclarationCleaningResponse {
    ingestion_key: IngestionKey,
    /// Absolute cleaned/declarations artifact directory.
    path: PathBuf,
    /// Raw member partitions, including empty partitions.
    member_partitions: usize,
    /// Declarations, including those with no funding.
    declarations: usize,
    /// Original funding occurrences.
    funding_entries: usize,
    /// Source-role funder observations across declaration and funding scopes.
    funders: usize,
}

#[derive(Serialize, JsonSchema)]
struct DeclarationResolutionResponse {
    ingestion_key: IngestionKey,
    /// Absolute resolved/declarations artifact directory.
    path: PathBuf,
    /// Source funder observations, including unresolved names.
    observations: usize,
    /// Original funding occurrences, counted once.
    payments: usize,
    /// Retained pair decisions between funder observations.
    pairs: usize,
}

#[derive(Serialize, JsonSchema)]
struct DeclarationLoadingResponse {
    ingestion_key: IngestionKey,
    /// Whether this call imported the run or confirmed an exact retry.
    outcome: DeclarationLoadOutcome,
    declarations: usize,
    /// Distinct resolved identities referenced by selected attributions.
    funders: usize,
    /// Original funding occurrences, including unavailable attributions.
    funding_entries: usize,
}

async fn latest(
    config: PathBuf,
) -> anyhow::Result<CliSuccess<IngestionResponse<IngestionLocation>>> {
    let config = LoaderConfig::try_from(&config)?;
    let ingestion = ExposedDataPipeline::latest_ingestion(&config.data_dir)
        .await?
        .map(|(path, ingestion_key)| IngestionLocation {
            ingestion_key,
            path,
        });
    Ok(CliSuccess::new(IngestionResponse { ingestion }))
}

async fn copy_latest_raw(
    config: PathBuf,
    ingestion_key: Option<IngestionKey>,
) -> anyhow::Result<CliSuccess<IngestionResponse<CopiedIngestion>>> {
    let config = LoaderConfig::try_from(&config)?;
    let ingestion_key = ingestion_key.unwrap_or_default();
    let ingestion = ExposedDataPipeline::copy_latest_raw(&config.data_dir, ingestion_key.clone())
        .await?
        .map(|(path, source_ingestion_key)| CopiedIngestion {
            source_ingestion_key,
            ingestion_key,
            path,
        });
    Ok(CliSuccess::new(IngestionResponse { ingestion }))
}

async fn declarations(
    stage: String,
    config: PathBuf,
    ingestion_key: Option<IngestionKey>,
) -> Response {
    let stage = match DeclarationIngestionStage::from_str(&stage) {
        Ok(stage) => stage,
        Err(error) => return Err::<Response, _>(error).into_response(),
    };
    match stage {
        DeclarationIngestionStage::Fetch => fetch_declarations(config, ingestion_key)
            .await
            .into_response(),
        DeclarationIngestionStage::Clean => clean_declarations(config, ingestion_key)
            .await
            .into_response(),
        DeclarationIngestionStage::Resolve => resolve_declarations(config, ingestion_key)
            .await
            .into_response(),
        DeclarationIngestionStage::Load => load_declarations(config, ingestion_key)
            .await
            .into_response(),
    }
}

async fn fetch_declarations(
    config: PathBuf,
    ingestion_key: Option<IngestionKey>,
) -> anyhow::Result<CliSuccess<StageAcknowledgement<DeclarationIngestionStage>>> {
    let config = DeclarationFetcherConfig::try_from(&config)?;
    let data_config = DataConfig::from_env()?;
    let api = ParliamentApiClient::new(config.batch_size)?;
    let db = ExposedDatabase::new(&data_config.connection_string).await?;
    let ingestion_key = ingestion_key.unwrap_or_default();
    let fs = ExposedDataPipeline::new_with_ingestion_key(&config.data_dir, ingestion_key.clone())?;
    DeclarationFetcherService::new(db, api, fs)
        .fetch_declarations()
        .await?;
    Ok(CliSuccess::new(StageAcknowledgement {
        path: std::path::absolute(config.data_dir)?
            .join(ingestion_key.to_string())
            .join("raw/declarations"),
        ingestion_key,
        stage: DeclarationIngestionStage::Fetch,
    }))
}

async fn resolve_declarations(
    config: PathBuf,
    ingestion_key: Option<IngestionKey>,
) -> anyhow::Result<CliSuccess<DeclarationResolutionResponse>> {
    let ingestion_key = ingestion_key
        .ok_or_else(|| anyhow::anyhow!("declarations resolve requires --ingestion-key"))?;
    let config = DeclarationResolverConfig::try_from(&config)?;
    let storage =
        ExposedDataPipeline::open_cleaned_declarations(&config.data_dir, ingestion_key.clone())?;
    let scorer = WeldrsFunderScorer::new()?;
    let summary = DeclarationResolverService::new(storage, scorer, config.candidate_budget)
        .resolve_declarations()
        .await?;
    Ok(CliSuccess::new(DeclarationResolutionResponse {
        path: std::path::absolute(config.data_dir)?
            .join(ingestion_key.to_string())
            .join("resolved/declarations"),
        ingestion_key,
        observations: summary.observations,
        payments: summary.payments,
        pairs: summary.pairs,
    }))
}

async fn load_declarations(
    config: PathBuf,
    ingestion_key: Option<IngestionKey>,
) -> anyhow::Result<CliSuccess<DeclarationLoadingResponse>> {
    let ingestion_key = ingestion_key
        .ok_or_else(|| anyhow::anyhow!("declarations load requires --ingestion-key"))?;
    let config = LoaderConfig::try_from(&config)?;
    let data_config = DataConfig::from_env()?;
    let storage =
        ExposedDataPipeline::open_resolved_declarations(&config.data_dir, ingestion_key.clone())?;
    let db = ExposedDatabase::new(&data_config.connection_string).await?;
    let summary = DeclarationLoaderService::new(storage, db)
        .load_declarations()
        .await?;
    Ok(CliSuccess::new(DeclarationLoadingResponse {
        ingestion_key,
        outcome: summary.outcome,
        declarations: summary.declarations,
        funders: summary.funders,
        funding_entries: summary.funding_entries,
    }))
}

async fn clean_declarations(
    config: PathBuf,
    ingestion_key: Option<IngestionKey>,
) -> anyhow::Result<CliSuccess<DeclarationCleaningResponse>> {
    let ingestion_key = ingestion_key
        .ok_or_else(|| anyhow::anyhow!("declarations clean requires --ingestion-key"))?;
    let config = LoaderConfig::try_from(&config)?;
    let fs =
        ExposedDataPipeline::open_existing_declarations(&config.data_dir, ingestion_key.clone())?;
    let summary = DeclarationCleanerService::new(fs)
        .clean_declarations()
        .await?;
    Ok(CliSuccess::new(DeclarationCleaningResponse {
        path: std::path::absolute(&config.data_dir)?
            .join(ingestion_key.to_string())
            .join("cleaned/declarations"),
        ingestion_key,
        member_partitions: summary.member_partitions,
        declarations: summary.declarations,
        funding_entries: summary.funding_entries,
        funders: summary.funders,
    }))
}

async fn members(
    stage: String,
    config: PathBuf,
    ingestion_key: Option<IngestionKey>,
) -> anyhow::Result<CliSuccess<StageAcknowledgement<MemberIngestionStage>>> {
    let stage = MemberIngestionStage::from_str(&stage)?;
    let ingestion_key = ingestion_key.unwrap_or_default();
    let data_dir = match stage {
        MemberIngestionStage::Fetch => {
            let config = FetcherConfig::try_from(&config)?;
            let api = ParliamentApiClient::new(config.batch_size)?;
            let fs = ExposedDataPipeline::new_with_ingestion_key(
                &config.data_dir,
                ingestion_key.clone(),
            )?;
            FetcherService::new(fs, api)
                .fetch_members(&EntityIngestionRequest {})
                .await?;
            config.data_dir
        }
        MemberIngestionStage::Load => {
            let config = LoaderConfig::try_from(&config)?;
            let data_config = DataConfig::from_env()?;
            let fs = ExposedDataPipeline::new_with_ingestion_key(
                &config.data_dir,
                ingestion_key.clone(),
            )?;
            let db = ExposedDatabase::new(&data_config.connection_string).await?;
            IngesterService::new(fs, db).load_members().await?;
            config.data_dir
        }
    };
    Ok(CliSuccess::new(StageAcknowledgement {
        path: std::path::absolute(data_dir)?
            .join(ingestion_key.to_string())
            .join("raw/members.parquet"),
        ingestion_key,
        stage,
    }))
}
//! JSON command results and their conversion to CLI output.

use schemars::JsonSchema;
use serde::Serialize;
use std::{
    io::{self, Write},
    process::ExitCode,
};

/// Generic JSON success response.
///
/// Payloads must expose their JSON schema as well as their serialization.
///
/// ```compile_fail
/// use exposed::inbound::cli::CliSuccess;
/// #[derive(serde::Serialize)]
/// struct Undocumented { count: usize }
/// let _ = CliSuccess::new(Undocumented { count: 1 });
/// ```
pub struct CliSuccess<S: Serialize + JsonSchema> {
    response: S,
}

impl<S: Serialize + JsonSchema> CliSuccess<S> {
    /// Creates a success response with a typed payload.
    pub const fn new(response: S) -> Self {
        Self { response }
    }
}

/// A serialized success or the original command failure.
pub struct Response(anyhow::Result<Vec<u8>>);

#[derive(Serialize, JsonSchema)]
pub(super) struct ErrorResponse {
    error: ErrorMessage,
}

#[derive(Serialize, JsonSchema)]
struct ErrorMessage {
    message: String,
}

impl Response {
    /// Writes one JSON document to stdout on success or stderr on failure.
    ///
    /// # Errors
    /// Returns an error if the selected output writer fails.
    pub fn write_to(self, mut stdout: impl Write, mut stderr: impl Write) -> io::Result<ExitCode> {
        let (mut bytes, writer, code): (_, &mut dyn Write, _) = match self.0 {
            Ok(bytes) => (bytes, &mut stdout, ExitCode::SUCCESS),
            Err(error) => {
                let payload = ErrorResponse {
                    error: ErrorMessage {
                        message: format!("{error:#}"),
                    },
                };
                let bytes = serde_json::to_vec(&payload).map_err(io::Error::other)?;
                (bytes, &mut stderr, ExitCode::FAILURE)
            }
        };
        bytes.push(b'\n');
        writer.write_all(&bytes)?;
        Ok(code)
    }
}

/// Converts a typed command result to a CLI response.
///
/// Wrap success payloads in [`CliSuccess`] before converting them.
///
/// ```compile_fail
/// use exposed::inbound::cli::IntoResponse;
/// "arbitrary text".into_response();
/// ```
pub trait IntoResponse {
    /// Converts this value to a response for the CLI boundary.
    fn into_response(self) -> Response;
}

impl IntoResponse for Response {
    fn into_response(self) -> Response {
        self
    }
}

impl<S: Serialize + JsonSchema> IntoResponse for CliSuccess<S> {
    fn into_response(self) -> Response {
        Response(serde_json::to_vec(&self.response).map_err(Into::into))
    }
}

impl<T, E> IntoResponse for Result<T, E>
where
    T: IntoResponse,
    E: Into<anyhow::Error>,
{
    fn into_response(self) -> Response {
        match self {
            Ok(value) => value.into_response(),
            Err(error) => Response(Err(error.into())),
        }
    }
}
# Database migrations

[SQLx CLI 0.9.0](https://github.com/launchbadge/sqlx/tree/v0.9.0/sqlx-cli) applies
versioned reversible migrations from `db/migrations`. Application code does not
apply migrations. Run these commands from the repository root:

```sh
sqlx migrate run --config sqlx.toml --source db/migrations
sqlx migrate info --config sqlx.toml --source db/migrations
```

Commands read the root `.env`. Set `DATABASE_URL` explicitly to target another
database. The root [`sqlx.toml`](../sqlx.toml) fixes the history table at
`public._sqlx_migrations`, regardless of the connection's search path.
Run only one import or migration against a database at a time.

## Add or revert a migration

Create a versioned pair with SQLx:

```sh
sqlx migrate add --source db/migrations --reversible describe_the_change
```

Write the schema change in the generated `.up.sql` file and its reverse in the
matching `.down.sql` file. Keep applied migrations immutable. Add new versions
for later changes instead of editing the baseline or creating `db/upgrades`
scripts. SQLx runs each direction in a transaction; omit `BEGIN` and `COMMIT`.

To revert the latest applied version:

```sh
sqlx migrate revert --config sqlx.toml --source db/migrations
```

Each invocation reverts one version. The current chain creates the normalized
member, declaration, funder, and funding tables, then adds the resolved declaration
loader, then adds the search indexes. Revert these in reverse order. Reverting
the loader drops its aliases, load history, and attribution columns. It also
restores unique funder names, so duplicate names cause the whole revert to fail
without changing the schema. Reverting the baseline removes all domain data,
`pg_trgm`, and the `exposed` schema. Unexpected dependencies fail transactionally
because the down migrations do not use `CASCADE`.

Test both a populated forward upgrade and the complete down/up cycle in an
isolated database before applying a new migration to imported data.

## Transition from the consolidated baseline once

Earlier development versions folded the loader and search changes into
`20260915000000_initial.up.sql`. The migration chain now assigns those changes
their own versions. An existing database with the consolidated baseline already
has the latest schema, but SQLx rejects the changed baseline checksum.

1. Back up the existing database and inspect `public._sqlx_migrations`.
   This procedure applies only when its sole successful migration is
   `20260915000000` and its schema already matches the consolidated baseline.
   If the schema or history differs, investigate those differences first.
2. Create an isolated database and run all current migrations there. Compare
   its schema with the existing database, including columns, nullability,
   defaults, constraints, indexes, functions, triggers, and the extension schema.
   Column order may differ. Verify that the existing database already contains
   every loader and search change. Save a record of the imported data for
   comparison after the transition.
3. Only after the schemas match, align the existing baseline checksum. From the
   repository root, with `DATABASE_URL` targeting the verified database:

   ```sh
   ingest/.venv/bin/python - <<'PY'
   import hashlib
   import os
   from pathlib import Path

   import psycopg
   from dotenv import load_dotenv

   load_dotenv('.env')
   checksum = hashlib.sha384(
       Path('db/migrations/20260915000000_initial.up.sql').read_bytes()
   ).digest()
   with psycopg.connect(os.environ['DATABASE_URL']) as conn:
       conn.execute('LOCK TABLE public._sqlx_migrations IN EXCLUSIVE MODE')
       history = conn.execute(
           'SELECT version, success FROM public._sqlx_migrations ORDER BY version'
       ).fetchall()
       if history != [(20260915000000, True)]:
           raise RuntimeError('Expected only the successful consolidated baseline')
       conn.execute(
           'UPDATE public._sqlx_migrations SET checksum = %s WHERE version = %s',
           (checksum, 20260915000000),
       )
   PY
   sqlx migrate run --config sqlx.toml --source db/migrations
   sqlx migrate info --config sqlx.toml --source db/migrations
   ```

4. Verify that all three versions succeeded, the schema still matches the
   isolated database, and imported records are unchanged. The loader and search
   up migrations tolerate their already-present objects and let SQLx record
   their versions normally. Do not use `migrate override skip` on the migration
   directory: it can mark unrelated pending migrations as applied.

This checksum alignment is a one-time transition, not the workflow for future
schema changes. For older dbmate databases or partially upgraded schemas,
compare and reconcile their actual schema and history separately before using
this chain. A history record alone does not prove schema compatibility.

## Timestamps

Each entity table has `created_at` and `updated_at`, both
`TIMESTAMPTZ NOT NULL DEFAULT now()`. A shared `BEFORE UPDATE` trigger function
sets `updated_at` when `OLD.* IS DISTINCT FROM NEW.*`; no-op updates and unchanged
upserts retain their timestamps. Updates preserve `created_at` unless the caller
explicitly changes it. PostgreSQL's `now()` is the transaction start time, so
changes within the same transaction share a timestamp.

`declaration_load_runs` records the first successful load time in `loaded_at`. Its
fingerprint and row counts remain fixed for that ingestion key.

All source date/time columns also use `TIMESTAMPTZ`. The importer converts
date-only values to midnight UTC at the persistence boundary, keeping calendar
dates in the domain model. It supplies timezone-aware parameters and reads stored
date values in UTC, independent of the database session's timezone. PostgreSQL
stores instants; their displayed offset depends on the session timezone.
`members.latest_membership_from` remains text: it is a constituency or membership
description, not a date.

New declaration ingestions populate registration dates when supplied by Parliament.
Missing source dates remain null.

SQL uses uppercase keywords/types, lowercase snake_case identifiers, and
schema-qualified domain objects.

## Deploy stored funder groups

The typed `ReviewedFamily` constants own the grouping policy in
`exposed/src/lib/domain/models/funder_grouping.rs`. Search and detail queries
read stored membership, direct evidence, and reviewed preferred names. Each family
sets `preferred_name` in the policy. Sparse `funder_group_names` rows keep these
display names separate from the minimum-UUID group identity and recorded names.
Schema migrations create empty projection tables; they do not apply the policy
to existing records.

Set `DATABASE_URL` to the target database. Before serving requests after the
grouping or preferred-name migration, stop the API, apply migrations, then run
the new binary against the same database. Use an ingestion key already loaded
into that database, with its unchanged raw, cleaned, and resolved artifacts. Set
`ingestion_key` to that key and use a YAML config whose `data_dir` contains the run.
`data latest --config exposed/config/cli-dev.yaml` shows the latest local
run, but confirm that the target database has already loaded it before proceeding.

Retry the load with those exact artifacts:

```sh
sqlx migrate run --config sqlx.toml --source db/migrations
cargo run --package exposed --bin exposed -- data declarations load --config exposed/config/cli-dev.yaml --ingestion-key "$ingestion_key"
psql "$DATABASE_URL" -X -v ON_ERROR_STOP=1 -c '
SELECT count(*) AS missing_memberships
FROM exposed.funders f
LEFT JOIN exposed.funder_alias_groups g ON g.funder_id = f.id
WHERE g.funder_id IS NULL;'
```

Require the load to report `Run already loaded` and `missing_memberships = 0`
before restarting the API. An exact retry refreshes all persisted funder groups,
direct evidence, and preferred names in one transaction under the declaration
loader lock. It preserves imported source data. Changed artifacts for an already
loaded key are rejected. Loading a new key can replace source data and prune
unreferenced funders and aliases, so use an exact retry for this procedure.

Repeat the exact retry after a reviewed policy update or manual changes to funder
names or aliases. Successful new declaration loads also refresh the projection in
their transaction. Keep the original artifacts available for future retries.

The alias evidence table uses a generated ID so long recorded names can be stored
without exceeding an index key limit.

